; 454  : void testVoiceFxDirectPsolaDiagnostic() {
; 455  :     using namespace webrc::dsp;
; 456  :     const ProcessSpec monoSpec{48000.0f, 128U, 1U};
; 457  :     const PitchEstimate inputEstimate{220.0f, 48000.0f / 220.0f, 0.99f, 0.3f, true};
; 458  :     std::vector<float> input(48000U);
; 459  :     for (std::size_t i = 0U; i < input.size(); ++i)
; 460  :         input[i] = 0.3f * std::sin(2.0 * 3.14159265358979323846 * 220.0 * i / 48000.0);
; 461  :     constexpr std::array<float, 6U> ratios{{0.5f, 0.75f, 0.94f, 1.0f, 1.5f, 2.0f}};
; 462  :     for (const float ratio : ratios) {
; 463  :         StreamingTdPsolaPitchShifter shifter;
; 464  :         std::vector<float> output(input.size());
; 465  :         check(shifter.prepare(monoSpec, 739U));
; 466  :         check(shifter.setPitchEstimate(inputEstimate, ratio));
; 467  :         for (std::uint32_t pos = 0U; pos < input.size(); pos += 128U)
; 468  :             check(shifter.processBlock(input.data() + pos, output.data() + pos, 128U));
; 469  :         double sum = 0.0;
; 470  :         std::vector<StereoFrame> monoStereo(12000U);
; 471  :         for (std::size_t i = 0U; i < monoStereo.size(); ++i) {
; 472  :             monoStereo[i].left = output[32000U + i];
; 473  :             sum += static_cast<double>(output[32000U + i]) * output[32000U + i];
; 474  :         }
; 475  :         const auto targetAmplitude = toneAmplitude(monoStereo, 0U, 12000U, false,
; 476  :                                                     48000.0, 220.0 * ratio);
; 477  :         const auto subharmonicAmplitude = toneAmplitude(monoStereo, 0U, 12000U, false,
; 478  :                                                          48000.0, 110.0 * ratio);
; 479  :         // Normalized autocorrelation can prefer a longer repeated period for a
; 480  :         // periodic resynthesis. Tone projections identify the intended F0 and
; 481  :         // explicitly reject a strong octave/subharmonic ambiguity.
; 482  :         check(targetAmplitude > 0.1 && targetAmplitude > 10.0 * subharmonicAmplitude);
; 483  :         std::fprintf(stderr, "direct PSOLA ratio %.2f rms %.6f autocorrCandidate %.3f "
; 484  :             "projection(target/subharmonic)=%.4f/%.4f\n", ratio,
; 485  :             std::sqrt(sum / 12000.0), estimateFrequency(monoStereo, 0U, 12000U, false,
; 486  :                                                         48000.0, 80.0, 1200.0),
; 487  :             targetAmplitude, subharmonicAmplitude);
; 488  :     }
; 489  : }
